    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        from sortedcontainers import SortedDict

        maxleft = SortedDict()
        n = len(nums)

        for i in range(n):
            target = nums[i] - i

            if target in maxleft:
                # Update the value for existing key
                prev_val = maxleft[target]
                maxleft[target] = max(prev_val, nums[i])

                # Find next index to potentially delete
                nextidx = maxleft.bisect_right(target)
                if nextidx < len(maxleft.keys()) and maxleft.peekitem(nextidx)[1] <= maxleft[target] - i:
                    del maxleft[maxleft.peekitem(nextidx)[0]]
            else:
                # Find previous index
                previdx = maxleft.bisect_left(target)

                if previdx == 0:
                    maxleft[target] = nums[i]
                else:
                    # Update with previous value
                    prev_val = maxleft.peekitem(previdx - 1)[1]
                    maxleft[target] = max(prev_val + nums[i], nums[i])

                # Find next index
                nextidx = maxleft.bisect_right(target)
                if nextidx < len(maxleft.keys()) and maxleft.peekitem(nextidx)[1] <= maxleft[target] - i:
                    del maxleft[maxleft.peekitem(nextidx)[0]]

